# ==============================================================================
# PANEL ESCOLAR v5: ASISTENCIA + NOTAS + DIAGNÓSTICO PDD (Versión Shinylive / Web)
# ==============================================================================

suppressPackageStartupMessages({
  library(shiny)
  library(bslib)
  library(readxl)
  library(dplyr)
  library(tidyr)
  library(ggplot2)
  library(scales)
  library(svglite)    # Requerido para renderizado de gráficos web / treemapify
  library(treemapify)
  library(ggrepel)
})

options(shiny.maxRequestSize = 60 * 1024^2)

# ==============================================================================
# CONSTANTES Y CONFIGURACIÓN
# ==============================================================================
UMBRAL_ASIST <- 85
NOTA_ROJA    <- 4.0

UMBRAL_LOGRO_ADEC <- 75L
UMBRAL_LOGRO_ELEM <- 60L
LV_ADEC <- sprintf("Adecuado (>=%d%%)", UMBRAL_LOGRO_ADEC)
LV_ELEM <- sprintf("Elemental (%d-%d%%)", UMBRAL_LOGRO_ELEM, UMBRAL_LOGRO_ADEC - 1L)
LV_INSU <- sprintf("Insuficiente (<%d%%)", UMBRAL_LOGRO_ELEM)
niveles_logro <- c(LV_ADEC, LV_ELEM, LV_INSU)
colores_logro <- stats::setNames(c("#2f6db5", "#f0a030", "#d64550"), niveles_logro)

UNIFICAR_ASIGNATURAS <- TRUE
ALIAS_ASIGNATURAS <- list(
  "Lenguaje" = c("LENGUAJE Y COMUNICACION", "LENGUA Y LITERATURA",
                 "LENGUAJE", "LENGUA CASTELLANA Y COMUNICACION"),
  "Matemática" = c("MATEMATICA", "MATEMATICAS"),
  "Historia"   = c("HISTORIA GEOGRAFIA Y CIENCIAS SOCIALES", "HISTORIA"),
  "Ciencias"   = c("CIENCIAS NATURALES", "CIENCIAS")
)

orden_meses <- c("marzo", "abril", "mayo", "junio", "julio",
                 "agosto", "septiembre", "octubre", "noviembre", "diciembre")

col_azul <- "#2f6db5"
col_rojo <- "#d64550"

niveles_rango <- c("< 4.0", "4.0-4.9", "5.0-5.9", "6.0-7.0")
colores_rango <- c("< 4.0" = "#d64550", "4.0-4.9" = "#f0a030",
                   "5.0-5.9" = "#7fb3e0", "6.0-7.0" = "#1e4f8f")

niveles_asist <- c("Destacada (>=95%)", "Normal (90-94%)",
                   "En riesgo (85-89%)", "Critica (<85%)")
colores_asist <- stats::setNames(c("#1e4f8f", "#7fb3e0", "#f0a030", "#d64550"), niveles_asist)

paleta_cat <- c("#2f6db5", "#14a3a0", "#f0a030", "#8e6bbf", "#d64550",
                "#6c8a3e", "#1e4f8f", "#c0508f", "#7fb3e0", "#8a6d3b")

# ==============================================================================
# FUNCIONES AUXILIARES
# ==============================================================================
rangos_nota <- function(x) {
  cut(x, breaks = c(0, 4, 5, 6, 7.1), right = FALSE, labels = niveles_rango)
}

clasificar_logro <- function(x) {
  out <- ifelse(x >= UMBRAL_LOGRO_ADEC, LV_ADEC,
                ifelse(x >= UMBRAL_LOGRO_ELEM, LV_ELEM, LV_INSU))
  out[is.na(x)] <- NA_character_
  out
}

categoria_asistencia <- function(p) {
  r <- cut(p, breaks = c(-Inf, UMBRAL_ASIST, 90, 95, Inf), right = FALSE,
           labels = rev(niveles_asist))
  factor(as.character(r), levels = niveles_asist)
}

racha_max <- function(x) {
  if (length(x) == 0 || !any(x, na.rm = TRUE)) return(0L)
  r <- rle(as.logical(x))
  as.integer(max(r$lengths[r$values %in% TRUE]))
}

norm_txt <- function(x) {
  d <- dim(x)
  x <- toupper(trimws(as.character(x)))
  x <- chartr("ÁÉÍÓÚÜÑÀÈÌÒÙÂÊÎÔÛ", "AEIOUUNAEIOUAEIOU", x)
  res <- gsub("[º°ª]", "", x)
  if (!is.null(d)) dim(res) <- d
  res
}

norm_nombre <- function(x) {
  x <- norm_txt(x)
  x <- gsub("[^A-Z ]", " ", x)
  trimws(gsub("\\s+", " ", x))
}

num_nota <- function(x) {
  v <- suppressWarnings(as.numeric(gsub(",", ".", x)))
  idx <- !is.na(v) & v >= 10 & v <= 70
  v[idx] <- v[idx] / 10
  v[!is.na(v) & (v < 1.0 | v > 7.0)] <- NA
  round(v, 1)
}

es_nombre_alumno <- function(x) {
  if (length(x) == 0) return(logical(0))
  t <- norm_txt(x)
  es_cabecera <- grepl(
    "^(ALUMN[OA]S?|ESTUDIANTES?|NOMBRES?|APELLIDOS?( Y NOMBRES?)?|PONDERACI[OÓ]N(ES)?|COEF(ICIENTE)?S?|PUNTAJES?|PROMEDIOS?|TOTALES?|RESUMEN|PORCENTAJES?|METAS?|CURSO|DOCENTE|PROFESOR(A)?|ASIGNATURA)$",
    t
  )
  es_meta <- grepl(
    "^(PROMEDIO|TOTAL|RESUMEN|PORCENTAJE|META|DIAS LECTIVOS|DIAS TRABAJADOS|#REF|#N/A|#VALOR|#DIV)",
    t
  )
  tiene_letras <- grepl("[A-Z]{2}", t)
  nzchar(trimws(x)) & nchar(trimws(x)) > 3 & !es_cabecera & !es_meta & tiene_letras
}

detectar_semestre <- function(txt) {
  t <- norm_txt(txt)
  if (length(t) == 0 || is.na(t)) return(NA_integer_)
  if (grepl("SEGUNDO|2\\s*[A-Z]{0,2}\\s*-?\\s*SEM|SEM[A-Z]*\\s*[-_ ]*2([^0-9]|$)", t)) return(2L)
  if (grepl("PRIMER|1\\s*[A-Z]{0,2}\\s*-?\\s*SEM|SEM[A-Z]*\\s*[-_ ]*1([^0-9]|$)", t)) return(1L)
  NA_integer_
}

aplicar_alias <- function(asig, forzar = FALSE) {
  if (!UNIFICAR_ASIGNATURAS && !forzar) return(asig)
  k <- trimws(gsub("\\s+", " ", norm_txt(asig)))
  for (nm in names(ALIAS_ASIGNATURAS)) {
    if (k %in% ALIAS_ASIGNATURAS[[nm]]) return(nm)
  }
  asig
}
asig_clave <- function(x) vapply(as.character(x), aplicar_alias, character(1),
                                 forzar = TRUE, USE.NAMES = FALSE)

parsear_curso <- function(texto) {
  if (is.null(texto) || length(texto) == 0 || is.na(texto[1]) || !nzchar(as.character(texto)[1])) return(NULL)
  t <- norm_txt(tools::file_path_sans_ext(texto))
  t <- gsub("([0-9]{1,2})(ERO|RO|DO|TO|MO|VO)", "\\1", t)
  tipo <- ifelse(grepl("\\b(MEDI|MEDIA|MEDIO)\\b", t), "M", "B")
  
  m <- regexec("\\b([0-9]{1,2})\\s*([A-Z])?\\s*(?:BASI[CA]O?S?|MEDI[OA]S?)\\b(?:\\s+([A-Z])\\b)?",
               t, perl = TRUE)
  r <- regmatches(t, m)[[1]]
  if (length(r) >= 2 && nzchar(r[2])) {
    letra <- ""
    if (length(r) >= 3 && nzchar(r[3])) letra <- r[3]
    else if (length(r) >= 4 && nzchar(r[4])) letra <- r[4]
    return(list(num = as.integer(r[2]), tipo = tipo, letra = letra))
  }
  
  m2 <- regexec("\\b([0-9]{1,2})\\s*([A-Z])?\\b", t, perl = TRUE)
  r2 <- regmatches(t, m2)[[1]]
  if (length(r2) >= 2 && nzchar(r2[2])) {
    letra <- if (length(r2) >= 3) r2[3] else ""
    return(list(num = as.integer(r2[2]), tipo = tipo, letra = letra))
  }
  NULL
}

etiqueta_curso <- function(p) {
  if (is.null(p)) return("")
  paste0(p$num, "° ", ifelse(p$tipo == "M", "MEDIO", "BÁSICO"),
         ifelse(nzchar(p$letra), paste0(" ", p$letra), ""))
}

etiqueta_curso_segura <- function(x) {
  if (is.null(x) || is.na(x) || !nzchar(as.character(x))) return("Sin Curso")
  p <- parsear_curso(x)
  if (is.null(p)) return(as.character(x))
  e <- etiqueta_curso(p)
  if (grepl("solo notas", x, ignore.case = TRUE)) e <- paste(e, "(solo notas)")
  e
}

etiquetar <- function(x) {
  x <- as.character(x)
  if (length(x) == 0) return(character(0))
  u <- unique(x)
  lab <- vapply(u, etiqueta_curso_segura, character(1), USE.NAMES = FALSE)
  unname(stats::setNames(lab, u)[x])
}

emparejar_curso <- function(p, cursos_asist) {
  if (is.null(p) || length(cursos_asist) == 0) return(NA_character_)
  for (nm in cursos_asist) {
    q <- parsear_curso(nm)
    if (is.null(q)) next
    if (q$num == p$num && q$tipo == p$tipo &&
        (q$letra == p$letra || !nzchar(q$letra) || !nzchar(p$letra))) {
      return(nm)
    }
  }
  NA_character_
}

emparejar_uno_a_uno <- function(nombres_asist, nombres_notas) {
  res <- stats::setNames(rep(NA_character_, length(nombres_notas)), nombres_notas)
  if (length(nombres_asist) == 0 || length(nombres_notas) == 0) return(res)
  
  ta <- strsplit(norm_nombre(nombres_asist), " ")
  tn <- strsplit(norm_nombre(nombres_notas), " ")
  cand <- list()
  
  for (i in seq_along(ta)) {
    for (j in seq_along(tn)) {
      a <- ta[[i]]; n <- tn[[j]]
      if (length(a) < 2 || length(n) < 2) next
      inter <- sum(a %in% n)
      minl <- min(length(a), length(n))
      ok <- (inter == minl) || (inter / minl >= 0.75 && a[1] == n[1])
      if (!ok) next
      sc <- inter / max(length(a), length(n)) +
        ifelse(a[1] == n[1], 0.3, 0) +
        ifelse(identical(a[1:2], n[1:2]), 0.3, 0)
      cand[[length(cand) + 1]] <- c(i = i, j = j, s = sc)
    }
  }
  if (length(cand) == 0) return(res)
  
  cm <- do.call(rbind, cand)
  cm <- cm[order(-cm[, "s"]), , drop = FALSE]
  usado_a <- rep(FALSE, length(ta))
  usado_n <- rep(FALSE, length(tn))
  for (k in seq_len(nrow(cm))) {
    i <- cm[k, "i"]; j <- cm[k, "j"]
    if (!usado_a[i] && !usado_n[j]) {
      res[j] <- nombres_asist[i]
      usado_a[i] <- TRUE
      usado_n[j] <- TRUE
    }
  }
  res
}

extraer_asignatura <- function(nombre_archivo) {
  base <- tools::file_path_sans_ext(nombre_archivo)
  nn <- norm_txt(base)
  m_pos <- regexpr("\\b[0-9]{1,2}\\s*[A-Z]?\\s*(?:B[AÁ]SIC[OA]S?|MED[IÍ][OA]S?)\\b(?:\\s+[A-Z]\\b)?", nn, perl = TRUE)
  
  if (m_pos > 1) {
    asig <- substr(base, 1, m_pos - 1)
  } else if (m_pos == 1) {
    match_len <- attr(m_pos, "match.length")
    resto <- substr(base, match_len + 1, nchar(base))
    resto <- gsub("(?i)(SEMESTRE|SEM|NOTAS|PLANILLA).*", "", resto, perl = TRUE)
    resto <- gsub("[-_0-9]+", " ", resto)
    asig <- trimws(resto)
  } else {
    asig <- base
  }
  
  asig <- gsub("(?i)(SEGUNDO|PRIMER|1ER|2DO|SEMESTRE|NOTAS|PLANILLA).*", "", asig, perl = TRUE)
  asig <- gsub("[-_0-9]+", " ", asig)
  asig <- tools::toTitleCase(tolower(trimws(gsub("\\s+", " ", asig))))
  
  if (!nzchar(asig) || nchar(asig) < 3) asig <- "General"
  aplicar_alias(asig)
}

detectar_encabezado <- function(nm) {
  exacto <- c("ALUMNOS", "ALUMNO", "ESTUDIANTES", "ESTUDIANTE", "NOMBRE",
              "NOMBRES", "APELLIDOS Y NOMBRES")
  f <- which(apply(nm, 1, function(r) any(r %in% exacto)))
  if (length(f) > 0) {
    c_nom <- which(nm[f[1], ] %in% exacto)[1]
    return(list(fila = f[1], col = c_nom))
  }
  f <- which(apply(nm, 1, function(r) any(grepl("^(ALUMN|ESTUDI|APELLID|NOMBR)", r))))
  if (length(f) == 0) return(NULL)
  c_nom <- which(grepl("^(ALUMN|ESTUDI|APELLID|NOMBR)", nm[f[1], ]))[1]
  list(fila = f[1], col = c_nom)
}

# Modificado para mayor compatibilidad con Shinylive en WebAssembly
escribir_csv_excel <- function(df, file) {
  write.csv2(df, file, row.names = FALSE, fileEncoding = "UTF-8")
}

tema_dash <- function(base = 12) {
  theme_minimal(base_size = base) +
    theme(
      text = element_text(color = "#334155"),
      plot.background = element_rect(fill = "white", color = NA),
      panel.background = element_rect(fill = "white", color = NA),
      plot.title = element_text(face = "bold", size = base + 2, hjust = 0, color = "#0f172a"),
      plot.subtitle = element_text(size = base - 1, hjust = 0, color = "#64748b",
                                   lineheight = 1.15, margin = margin(b = 8)),
      plot.title.position = "plot",
      axis.title = element_text(face = "bold", size = base - 1, color = "#475569"),
      axis.text = element_text(color = "#334155"),
      panel.grid.minor = element_blank(),
      panel.grid.major = element_line(color = "#e8edf3", linewidth = 0.4),
      strip.text = element_text(face = "bold", color = "#0f172a"),
      strip.background = element_rect(fill = "#eef3f9", color = NA),
      legend.title = element_text(face = "bold", size = base - 1),
      legend.text = element_text(size = base - 1),
      legend.position = "bottom",
      plot.margin = margin(10, 16, 10, 10)
    )
}

kpi_ui <- function(id, titulo, icono, accent = "#2f6db5", extra = NULL) {
  div(class = "kpi-card", style = paste0("--accent:", accent, ";"),
      div(class = "kpi-icon", style = paste0("background:", accent, "1f; color:", accent, ";"), icono),
      div(class = "kpi-body",
          div(class = "kpi-title", titulo),
          uiOutput(id),
          extra))
}
kpi_val <- function(valor, clase = "") tags$div(class = paste("kpi-val", clase), valor)

tab_intro <- function(titulo, detalle = NULL) {
  div(class = "tab-intro",
      div(class = "tab-intro-title", titulo),
      if (!is.null(detalle)) div(class = "tab-intro-sub", detalle))
}

pcard <- function(titulo, id, alto = "460px", ...) {
  card(full_screen = TRUE, card_header(titulo), plotOutput(id, height = alto, ...))
}
tcard <- function(titulo, id, scroll = TRUE) {
  card(card_header(titulo),
       if (scroll) div(class = "scroll-box", tableOutput(id)) else tableOutput(id))
}
side_title <- function(txt) tags$div(class = "side-title", txt)

# ==============================================================================
# LECTURA DE ASISTENCIA
# ==============================================================================
leer_asistencia_archivo <- function(ruta, nombre_archivo) {
  info <- parsear_curso(nombre_archivo)
  if (is.null(info)) stop("no pude identificar el curso en el nombre del archivo")
  
  curso <- tools::file_path_sans_ext(nombre_archivo)
  hojas <- readxl::excel_sheets(ruta)
  hojas_meses <- hojas[tolower(trimws(hojas)) %in% orden_meses]
  if (length(hojas_meses) == 0) {
    hojas_meses <- hojas[!grepl("(?i)(instruccion|portada|acumulad|resumen|grafic)", hojas, perl = TRUE)]
  }
  if (length(hojas_meses) == 0) stop("no se encontraron hojas de asistencia")
  
  datos_totales <- list()
  
  for (h in hojas_meses) {
    raw <- suppressMessages(read_excel(ruta, sheet = h, col_names = FALSE,
                                       col_types = "text", .name_repair = "minimal"))
    m <- as.matrix(raw)
    m[is.na(m)] <- ""
    m[] <- trimws(m)
    nm <- m
    nm[] <- norm_txt(m)
    
    enc <- detectar_encabezado(nm)
    if (is.null(enc) || is.na(enc$col)) next
    fila_h <- enc$fila
    c_nom <- enc$col
    if (fila_h >= nrow(m)) next
    
    filas_posibles <- (fila_h + 1):nrow(m)
    filas <- filas_posibles[es_nombre_alumno(m[filas_posibles, c_nom])]
    if (length(filas) < 3) next
    
    nombres <- m[filas, c_nom]
    mes_actual <- tolower(trimws(h))
    if (!mes_actual %in% orden_meses) {
      cab_txt <- tolower(paste(nm[1:fila_h, ], collapse = " "))
      for (mn in orden_meses) {
        if (grepl(paste0("\\b", mn, "\\b"), cab_txt)) { mes_actual <- mn; break }
      }
    }
    
    cols_asist <- which(seq_len(ncol(m)) > c_nom)
    if (length(cols_asist) == 0) next
    sub_m  <- m[filas, cols_asist, drop = FALSE]
    sub_nm <- nm[filas, cols_asist, drop = FALSE]
    
    sub_estado <- matrix(NA_character_, nrow = nrow(sub_m), ncol = ncol(sub_m))
    sub_estado[grepl("^(A|ASIST|ASISTIO|PRESENTE|P|1|1\\.0|•|\\*)$", sub_nm)] <- "Asistió"
    sub_estado[grepl("^(F|FALTO|AUSENTE|INASISTENTE|I|0|0\\.0|J|JUSTIFICADO)$", sub_nm)] <- "Faltó"
    
    idx <- which(!is.na(sub_estado), arr.ind = TRUE)
    if (nrow(idx) > 0) {
      real_col <- cols_asist[idx[, 2]]
      dia_hdr <- m[fila_h, real_col]
      dia <- ifelse(nzchar(dia_hdr), dia_hdr, as.character(real_col))
      datos_totales[[length(datos_totales) + 1]] <- data.frame(
        Nombre = nombres[idx[, 1]],
        Mes = mes_actual,
        Dia = dia,
        Valor = sub_m[idx],
        Estado = sub_estado[idx],
        Curso = curso,
        stringsAsFactors = FALSE
      )
    }
  }
  
  if (length(datos_totales) == 0) stop("no encontré registros de asistencia válidos")
  bind_rows(datos_totales)
}

# ==============================================================================
# LECTURA DE NOTAS
# ==============================================================================
det_cols_vacio <- function() {
  data.frame(Nombre_Notas = character(), Semestre = integer(), Evaluacion = integer(),
             Nota = numeric(), Etiqueta = character(), Asignatura = character(),
             stringsAsFactors = FALSE)
}
prom_cols_vacio <- function() {
  data.frame(Nombre_Notas = character(), Semestre = integer(), Promedio = numeric(),
             Asignatura = character(), stringsAsFactors = FALSE)
}

leer_notas_archivo <- function(ruta, nombre_archivo) {
  info <- parsear_curso(nombre_archivo)
  if (is.null(info)) stop("no pude identificar el curso en el nombre del archivo")
  
  asignatura <- extraer_asignatura(nombre_archivo)
  sem_archivo <- detectar_semestre(tools::file_path_sans_ext(nombre_archivo))
  if (is.na(sem_archivo)) sem_archivo <- 1L
  
  raw <- suppressMessages(read_excel(ruta, sheet = 1, col_names = FALSE,
                                     col_types = "text", .name_repair = "minimal"))
  m <- as.matrix(raw)
  m[is.na(m)] <- ""
  m[] <- trimws(m)
  nm <- m
  nm[] <- norm_txt(m)
  
  enc <- detectar_encabezado(nm)
  if (is.null(enc) || is.na(enc$col)) stop("no encontré la columna 'Alumnos' en la planilla")
  fila_h <- enc$fila
  c_nom <- enc$col
  if (fila_h >= nrow(m)) stop("no hay filas bajo el encabezado")
  
  filas_posibles <- (fila_h + 1):nrow(m)
  filas <- filas_posibles[es_nombre_alumno(m[filas_posibles, c_nom])]
  if (length(filas) == 0) stop("no hay alumnos listados bajo el encabezado")
  nombres <- m[filas, c_nom]
  
  rows_h <- seq(max(1, fila_h - 1), min(nrow(nm), fila_h + 1))
  excluir <- function(j) {
    any(grepl("(ASIST|%|PORC|EDAD|FECHA|OBSERV|^RUT$|^RUN$|^CURSO$|^N$)", nm[rows_h, j]))
  }
  es_prom <- function(j) {
    any(grepl("^(NOTA|PROM|PROMEDIO|PROMEDIO FINAL|NOTA FINAL|FINAL|NF)$",
              nm[c(fila_h, min(nrow(nm), fila_h + 1)), j]))
  }
  
  cols_validas <- which(vapply(seq_len(ncol(m)), function(j) {
    j > c_nom && !excluir(j) && any(!is.na(num_nota(m[filas, j])))
  }, logical(1)))
  
  if (length(cols_validas) == 0) {
    diag <- sprintf("Encabezado en fila %d, %d alumnos. Planilla sin notas ingresadas.", fila_h, length(nombres))
    return(list(info = info, asignatura = asignatura, sem_archivo = sem_archivo,
                det = det_cols_vacio(), prom = prom_cols_vacio(),
                nombres = unique(nombres), diag = diag))
  }
  
  sem_lab <- rep(NA_integer_, ncol(m))
  for (r in seq(max(1, fila_h - 4), fila_h)) {
    for (j in seq_len(ncol(m))) {
      if (grepl("SEM", nm[r, j])) {
        s <- detectar_semestre(nm[r, j])
        if (!is.na(s)) sem_lab[j] <- s
      }
    }
  }
  asignar_sem <- function(j) {
    cand <- which(!is.na(sem_lab) & seq_along(sem_lab) <= j)
    if (length(cand) > 0) sem_lab[max(cand)] else sem_archivo
  }
  
  c_prom <- cols_validas[vapply(cols_validas, es_prom, logical(1))]
  if (length(c_prom) > 2) c_prom <- integer(0)
  cols_eval <- setdiff(cols_validas, c_prom)
  if (length(cols_eval) == 0 && length(c_prom) > 0) {
    cols_eval <- c_prom
    c_prom <- integer(0)
  }
  
  det <- det_cols_vacio()
  if (length(cols_eval) > 0) {
    sems <- vapply(cols_eval, asignar_sem, integer(1))
    idx <- ave(seq_along(cols_eval), sems, FUN = seq_along)
    sub_eval <- matrix(num_nota(m[filas, cols_eval]), nrow = length(filas), ncol = length(cols_eval))
    idx_v <- which(!is.na(sub_eval), arr.ind = TRUE)
    if (nrow(idx_v) > 0) {
      det <- data.frame(
        Nombre_Notas = nombres[idx_v[, 1]],
        Semestre = as.integer(sems[idx_v[, 2]]),
        Evaluacion = as.integer(idx[idx_v[, 2]]),
        Nota = sub_eval[idx_v],
        stringsAsFactors = FALSE
      )
      det$Etiqueta <- paste0("S", det$Semestre, " · Nota ", det$Evaluacion)
      det$Asignatura <- asignatura
    }
  }
  
  prom <- prom_cols_vacio()
  if (length(c_prom) > 0) {
    sub_pr <- matrix(num_nota(m[filas, c_prom]), nrow = length(filas), ncol = length(c_prom))
    idx_p <- which(!is.na(sub_pr), arr.ind = TRUE)
    if (nrow(idx_p) > 0) {
      prom <- data.frame(
        Nombre_Notas = nombres[idx_p[, 1]],
        Semestre = as.integer(vapply(c_prom[idx_p[, 2]], asignar_sem, integer(1))),
        Promedio = sub_pr[idx_p],
        Asignatura = asignatura,
        stringsAsFactors = FALSE
      )
    }
  }
  if (nrow(prom) == 0 && nrow(det) > 0) {
    prom <- det %>%
      group_by(Nombre_Notas, Semestre, Asignatura) %>%
      summarise(Promedio = round(mean(Nota), 1), .groups = "drop") %>%
      as.data.frame()
  }
  
  list(info = info, asignatura = asignatura, sem_archivo = sem_archivo,
       det = det, prom = prom, nombres = unique(nombres),
       diag = sprintf("%d alumnos; %d evaluaciones leídas.", length(unique(nombres)), length(cols_eval)))
}

# ==============================================================================
# LECTURA DE DIAGNÓSTICO PDD
# ==============================================================================
leer_pdd_archivo <- function(ruta, nombre_archivo) {
  hojas <- readxl::excel_sheets(ruta)
  hoja_sel <- if ("Datos Curso" %in% hojas) "Datos Curso" else hojas[1]
  
  raw <- suppressMessages(read_excel(ruta, sheet = hoja_sel, col_types = "text", .name_repair = "minimal"))
  df <- as.data.frame(raw, stringsAsFactors = FALSE)
  names(df) <- gsub("[^A-Z0-9]", "_", toupper(chartr("ÁÉÍÓÚÜÑ", "AEIOUUN", trimws(names(df)))))
  
  cols_necesarias <- c("NIVEL", "CURSO", "ASIGNATURA", "RUT", "PORCENTAJE_DE_LOGRO", "NOTA", "PUNTAJE")
  if (!all(cols_necesarias %in% names(df))) {
    stop("el archivo no tiene el formato de diagnóstico PDD (hoja 'Datos Curso').")
  }
  
  txt <- function(col) {
    if (col %in% names(df)) {
      v <- trimws(as.character(df[[col]]))
      v[is.na(v)] <- ""
      v
    } else rep("", nrow(df))
  }
  
  nivel_raw <- toupper(txt("NIVEL"))
  curso_letra <- toupper(txt("CURSO"))
  curso_letra <- ifelse(nchar(curso_letra) > 2, sub(".*\\b([A-Z])$", "\\1", curso_letra), curso_letra)
  tipo_c <- ifelse(grepl("MEDIO", nivel_raw), "MEDIO", "BÁSICO")
  num_c <- gsub("[^0-9]", "", nivel_raw)
  curso_fmt <- paste0(num_c, "° ", tipo_c, ifelse(nzchar(curso_letra), paste0(" ", curso_letra), ""))
  
  rut_val <- txt("RUT"); dv_val <- txt("DV")
  nombre_completo <- trimws(gsub("\\s+", " ", paste(txt("APELLIDO_PATERNO"), txt("APELLIDO_MATERNO"),
                                                    txt("PRIMER_NOMBRE"), txt("SEGUNDO_NOMBRE"))))
  sin_nombre <- !nzchar(nombre_completo)
  nombre_completo[sin_nombre] <- paste0("RUT ", rut_val[sin_nombre], "-", dv_val[sin_nombre])
  nombre_completo <- tools::toTitleCase(tolower(nombre_completo))
  
  asig_clean <- tools::toTitleCase(tolower(trimws(df$ASIGNATURA)))
  asig_clean <- ifelse(grepl("Lenguaje", asig_clean, ignore.case = TRUE), "Lenguaje",
                       ifelse(grepl("Matemat", asig_clean, ignore.case = TRUE), "Matemática", asig_clean))
  
  logro_num <- suppressWarnings(as.numeric(gsub(",", ".", df$PORCENTAJE_DE_LOGRO)))
  if (any(!is.na(logro_num)) && max(logro_num, na.rm = TRUE) <= 1) logro_num <- logro_num * 100
  nota_num <- suppressWarnings(as.numeric(gsub(",", ".", df$NOTA)))
  pts_num  <- suppressWarnings(as.numeric(gsub(",", ".", df$PUNTAJE)))
  sexo_val <- toupper(txt("SEXO"))
  sexo_val[!sexo_val %in% c("F", "M")] <- NA_character_
  colegio <- txt("COLEGIO")[1]
  if (is.na(colegio) || !nzchar(colegio)) colegio <- "Colegio"
  
  out <- data.frame(
    Colegio     = colegio,
    Curso       = curso_fmt,
    Alumno      = nombre_completo,
    RUT         = paste0(rut_val, "-", dv_val),
    Sexo        = sexo_val,
    Asignatura  = asig_clean,
    Logro       = logro_num,
    Nota        = nota_num,
    Puntaje     = pts_num,
    Nivel_Logro = clasificar_logro(logro_num),
    Archivo     = nombre_archivo,
    stringsAsFactors = FALSE
  )
  out <- out[!is.na(out$Logro), , drop = FALSE]
  if (nrow(out) == 0) stop("el archivo no contiene resultados con % de logro.")
  out
}

# ==============================================================================
# ENTRADAS
# ==============================================================================
nueva_entrada <- function(nombre, tipo, ok, estado, detalle, curso_txt = "-",
                          asignatura = "-", semestre = "-", n_alumnos = NA_integer_,
                          n_notas = NA_integer_, res = NULL) {
  list(nombre = nombre, tipo = tipo, ok = ok, estado = estado, detalle = detalle,
       curso_txt = curso_txt, asignatura = asignatura, semestre = semestre,
       n_alumnos = n_alumnos, n_notas = n_notas, res = res)
}

procesar_asistencia <- function(ruta, nombre) {
  r <- tryCatch(leer_asistencia_archivo(ruta, nombre), error = function(e) e)
  if (inherits(r, "error")) {
    return(nueva_entrada(nombre, "Asistencia", FALSE, "Error", conditionMessage(r)))
  }
  nueva_entrada(
    nombre, "Asistencia", TRUE, "OK",
    sprintf("%d meses leídos, %d registros.", length(unique(r$Mes)), nrow(r)),
    curso_txt = etiqueta_curso_segura(unique(r$Curso)[1]),
    n_alumnos = length(unique(r$Nombre)), res = r
  )
}

procesar_notas <- function(ruta, nombre) {
  r <- tryCatch(leer_notas_archivo(ruta, nombre), error = function(e) e)
  if (inherits(r, "error")) {
    return(nueva_entrada(nombre, "Notas", FALSE, "Error", conditionMessage(r)))
  }
  sin_notas <- nrow(r$det) == 0 && nrow(r$prom) == 0
  sems <- sort(unique(c(r$det$Semestre, r$prom$Semestre)))
  if (length(sems) == 0) sems <- r$sem_archivo
  nueva_entrada(
    nombre, "Notas", TRUE, if (sin_notas) "Sin notas aún" else "OK", r$diag,
    curso_txt = etiqueta_curso(r$info), asignatura = r$asignatura,
    semestre = paste(sems, collapse = ", "),
    n_alumnos = length(r$nombres), n_notas = nrow(r$det), res = r
  )
}

procesar_pdd <- function(ruta, nombre) {
  r <- tryCatch(leer_pdd_archivo(ruta, nombre), error = function(e) e)
  if (inherits(r, "error")) {
    return(nueva_entrada(nombre, "PDD (Diagnóstico)", FALSE, "Error", conditionMessage(r)))
  }
  nueva_entrada(
    nombre, "PDD (Diagnóstico)", TRUE, "OK",
    sprintf("%d evaluados (logro medio %.1f%%).", nrow(r), mean(r$Logro, na.rm = TRUE)),
    curso_txt = paste(unique(r$Curso), collapse = ", "),
    asignatura = paste(unique(r$Asignatura), collapse = ", "),
    n_alumnos = length(unique(r$RUT)), n_notas = nrow(r), res = r
  )
}

