pg_alumno <- function(df) {
  if (nrow(df) == 0) {
    return(data.frame(Curso = character(), Alumno = character(), PG = numeric(),
                      N_Asig = integer(), N_Rojas = integer(), stringsAsFactors = FALSE))
  }
  df %>%
    filter(es_nombre_alumno(Alumno)) %>%
    group_by(Curso, Alumno) %>%
    summarise(PG = round(mean(Promedio), 1), N_Asig = n(),
              N_Rojas = sum(Promedio < NOTA_ROJA), .groups = "drop")
}

