# ==============================================================================
# SERVER
# ==============================================================================
server <- function(input, output, session) {
  
  asistencia_parseada <- reactiveVal(list())
  notas_parseadas     <- reactiveVal(list())
  pdd_parseada        <- reactiveVal(list())
  
  datos_modal_rojos  <- reactiveVal(NULL)
  datos_modal_rangos <- reactiveVal(NULL)
  datos_modal_pdd    <- reactiveVal(NULL)
  
  agregar_archivos <- function(x, almacen, procesador, etiqueta) {
    if (is.null(x) || nrow(x) == 0) return(invisible())
    x$id <- paste(x$name, x$size, sep = "|")
    actual <- almacen()
    nuevos <- x[!x$id %in% names(actual), , drop = FALSE]
    if (nrow(nuevos) == 0) return(invisible())
    
    withProgress(message = paste("Leyendo", etiqueta), value = 0, {
      for (i in seq_len(nrow(nuevos))) {
        incProgress(1 / nrow(nuevos), detail = nuevos$name[i])
        actual[[nuevos$id[i]]] <- procesador(nuevos$datapath[i], nuevos$name[i])
      }
    })
    almacen(actual)
    
    est <- vapply(actual[nuevos$id], function(e) e$estado, character(1))
    showNotification(
      sprintf("%d archivo(s) de %s: %d OK, %d sin datos aún, %d con error. Detalle en 'Control de Carga'.",
              length(est), etiqueta, sum(est == "OK"), sum(est == "Sin notas aún"), sum(est == "Error")),
      type = if (any(est == "Error")) "warning" else "message", duration = 7
    )
  }
  
  observeEvent(input$archivo_excel, {
    agregar_archivos(input$archivo_excel, asistencia_parseada, procesar_asistencia, "asistencia")
  }, ignoreInit = TRUE)
  observeEvent(input$archivo_notas, {
    agregar_archivos(input$archivo_notas, notas_parseadas, procesar_notas, "notas")
  }, ignoreInit = TRUE)
  observeEvent(input$archivo_pdd, {
    agregar_archivos(input$archivo_pdd, pdd_parseada, procesar_pdd, "PDD")
  }, ignoreInit = TRUE)
  
  observeEvent(input$btn_limpiar, {
    asistencia_parseada(list()); notas_parseadas(list()); pdd_parseada(list())
    showNotification("Todos los datos fueron borrados.", type = "message")
  })
  
  todos_los_cursos <- reactive({
    ok <- Filter(function(e) isTRUE(e$ok), asistencia_parseada())
    if (length(ok) == 0) return(list())
    todo <- bind_rows(lapply(ok, function(e) e$res))
    split(todo, todo$Curso)
  })
  
  asist_cargada <- reactive(length(todos_los_cursos()) > 0)
  
  datos_globales <- reactive({
    cursos <- todos_los_cursos()
    if (length(cursos) == 0) return(asist_vacia)
    bind_rows(cursos) %>% mutate(Mes = factor(tolower(as.character(Mes)), levels = orden_meses))
  })
  
  asist_resumen <- reactive({
    d <- datos_globales()
    if (nrow(d) == 0) return(asist_res_vacio)
    d %>%
      mutate(Dia_num = suppressWarnings(as.integer(as.numeric(Dia))),
             Dia_num = ifelse(is.na(Dia_num), 0L, Dia_num)) %>%
      arrange(Curso, Nombre, Mes, Dia_num) %>%
      group_by(Curso, Nombre) %>%
      summarise(Dias = n(),
                Asistidos = sum(Estado == "Asistió"),
                Faltas = sum(Estado == "Faltó"),
                Pct = Asistidos / Dias * 100,
                MaxRacha = racha_max(Estado == "Faltó"),
                .groups = "drop") %>%
      mutate(Categoria = categoria_asistencia(Pct))
  })
  
  notas_data <- reactive({
    entradas <- Filter(function(e) isTRUE(e$ok), notas_parseadas())
    if (length(entradas) == 0) {
      return(list(det = det_vacio, prom = prom_vacio, vinc = vinc_vacio))
    }
    
    asist <- todos_los_cursos()
    cursos_asist <- names(asist)
    
    info_c <- lapply(entradas, function(e) {
      ca <- emparejar_curso(e$res$info, cursos_asist)
      list(curso = if (is.na(ca)) paste0(etiqueta_curso(e$res$info), " (solo notas)") else ca,
           con_asist = !is.na(ca))
    })
    cursos <- vapply(info_c, function(x) x$curso, character(1))
    
    vinc_l <- list()
    for (cu in unique(cursos)) {
      idx <- which(cursos == cu)
      nombres_notas <- unique(unlist(lapply(entradas[idx], function(e) e$res$nombres)))
      nombres_notas <- nombres_notas[es_nombre_alumno(nombres_notas)]
      if (length(nombres_notas) == 0) next
      alumnos_asist <- if (cu %in% cursos_asist) unique(asist[[cu]]$Nombre) else character(0)
      mapeo <- emparejar_uno_a_uno(alumnos_asist, nombres_notas)
      vinc_l[[length(vinc_l) + 1]] <- data.frame(
        Curso = cu,
        Nombre_Notas = nombres_notas,
        Alumno = ifelse(is.na(mapeo), nombres_notas, unname(mapeo)),
        Vinculado = !is.na(mapeo),
        Curso_con_asistencia = cu %in% cursos_asist,
        stringsAsFactors = FALSE
      )
    }
    vinc <- if (length(vinc_l) > 0) bind_rows(vinc_l) else vinc_vacio
    mapa <- vinc[, c("Curso", "Nombre_Notas", "Alumno", "Vinculado")]
    
    det_l <- list(); prom_l <- list()
    for (k in seq_along(entradas)) {
      r <- entradas[[k]]$res
      if (nrow(r$det) > 0)  { d <- r$det;  d$Curso <- cursos[k]; det_l[[length(det_l) + 1]]   <- d }
      if (nrow(r$prom) > 0) { p <- r$prom; p$Curso <- cursos[k]; prom_l[[length(prom_l) + 1]] <- p }
    }
    
    det <- if (length(det_l) > 0) left_join(bind_rows(det_l), mapa, by = c("Curso", "Nombre_Notas")) else det_vacio
    prom <- if (length(prom_l) > 0) left_join(bind_rows(prom_l), mapa, by = c("Curso", "Nombre_Notas")) else prom_vacio
    
    det <- det %>% filter(es_nombre_alumno(Alumno))
    prom <- prom %>% filter(es_nombre_alumno(Alumno))
    
    list(det = det, prom = prom, vinc = vinc)
  })
  
  notas_cargadas <- reactive({
    nd <- notas_data()
    nrow(nd$det) > 0 || nrow(nd$prom) > 0
  })
  
  filtra_asig <- function(df) {
    if (nrow(df) == 0 || is.null(input$select_asignatura) || input$select_asignatura == "Todas") return(df)
    df %>% filter(Asignatura == input$select_asignatura)
  }
  filtra_sem <- function(df) {
    if (nrow(df) == 0 || is.null(input$select_semestre) || input$select_semestre == "Todos") return(df)
    sem <- suppressWarnings(as.integer(gsub("[^0-9]", "", input$select_semestre)))
    df %>% filter(Semestre == sem)
  }
  
  observeEvent(notas_data(), {
    nd <- notas_data()
    asignaturas <- sort(unique(c(nd$det$Asignatura, nd$prom$Asignatura)))
    choices <- c("Todas", asignaturas)
    sel <- if (!is.null(input$select_asignatura) && input$select_asignatura %in% choices) input$select_asignatura else "Todas"
    updateSelectInput(session, "select_asignatura", choices = choices, selected = sel)
    
    semestres <- sort(unique(c(nd$det$Semestre, nd$prom$Semestre)))
    semestres <- semestres[!is.na(semestres)]
    choices_s <- c("Todos", paste("Semestre", semestres))
    sel_s <- if (!is.null(input$select_semestre) && input$select_semestre %in% choices_s) input$select_semestre else "Todos"
    updateSelectInput(session, "select_semestre", choices = choices_s, selected = sel_s)
  })
  
  prom_base <- reactive({
    nd <- notas_data()
    if (nrow(nd$det) == 0 && nrow(nd$prom) == 0) return(prom_vacio)
    
    calc <- nd$det %>%
      filter(!is.na(Alumno)) %>%
      group_by(Curso, Asignatura, Alumno, Semestre) %>%
      summarise(Prom_calc = round(mean(Nota), 1), .groups = "drop")
    
    p <- nd$prom %>%
      filter(!is.na(Alumno)) %>%
      select(Curso, Asignatura, Alumno, Semestre, Promedio)
    
    if (nrow(calc) > 0) {
      p <- full_join(p, calc, by = c("Curso", "Asignatura", "Alumno", "Semestre")) %>%
        mutate(Promedio = ifelse(is.na(Promedio), Prom_calc, Promedio))
    }
    p <- p %>% filter(!is.na(Promedio))
    p <- filtra_sem(p)
    if (nrow(p) == 0) return(prom_vacio)
    
    p %>%
      group_by(Curso, Asignatura, Alumno) %>%
      summarise(Promedio = round(mean(Promedio), 1), .groups = "drop")
  })
  
  prom_filtrado <- reactive(filtra_asig(prom_base()))
  
  det_filtrado <- reactive({
    d <- notas_data()$det
    if (nrow(d) == 0) return(det_vacio)
    filtra_asig(filtra_sem(d))
  })
  
  prom_curso <- reactive({
    req(input$select_curso)
    p <- prom_filtrado()
    if (input$select_curso == "TODOS") return(p)
    p %>% filter(Curso == input$select_curso)
  })
  
  catalogo_cursos <- reactive({
    unique(c(names(todos_los_cursos()), notas_data()$vinc$Curso))
  })
  
  nombres_referencia <- reactive({
    a <- if (asist_cargada()) {
      datos_globales() %>% distinct(Curso, Alumno = Nombre)
    } else data.frame(Curso = character(), Alumno = character(), stringsAsFactors = FALSE)
    v <- notas_data()$vinc
    n <- if (nrow(v) > 0) {
      v %>% distinct(Curso, Alumno)
    } else data.frame(Curso = character(), Alumno = character(), stringsAsFactors = FALSE)
    bind_rows(a, n) %>% distinct()
  })
  
  pdd_data <- reactive({
    entradas <- Filter(function(e) isTRUE(e$ok), pdd_parseada())
    if (length(entradas) == 0) return(pdd_vacio)
    d <- bind_rows(lapply(entradas, function(e) e$res))
    
    catalogo <- catalogo_cursos()
    cursos_u <- unique(d$Curso)
    map_c <- vapply(cursos_u, function(cu) {
      ca <- emparejar_curso(parsear_curso(cu), catalogo)
      if (is.na(ca)) cu else ca
    }, character(1))
    d$Curso_Canon <- unname(map_c[d$Curso])
    
    ref_all <- nombres_referencia()
    d$Alumno_Canon <- d$Alumno
    d$Vinculado <- FALSE
    for (cc in unique(d$Curso_Canon)) {
      ref <- unique(ref_all$Alumno[ref_all$Curso == cc])
      if (length(ref) == 0) next
      idx <- which(d$Curso_Canon == cc)
      nom_pdd <- unique(d$Alumno[idx])
      mp <- emparejar_uno_a_uno(ref, nom_pdd)
      rep_n <- unname(mp[d$Alumno[idx]])
      ok <- !is.na(rep_n)
      d$Alumno_Canon[idx[ok]] <- rep_n[ok]
      d$Vinculado[idx[ok]] <- TRUE
    }
    d
  })
  
  pdd_cargado <- reactive(nrow(pdd_data()) > 0)
  
  cursos_todos <- reactive({
    a <- if (asist_cargada()) names(todos_los_cursos()) else character(0)
    v <- notas_data()$vinc$Curso
    p <- if (pdd_cargado()) unique(pdd_data()$Curso_Canon) else character(0)
    unique(c(a, v, p))
  })
  
  observeEvent(cursos_todos(), {
    cursos <- cursos_todos()
    if (length(cursos) == 0) {
      updateSelectInput(session, "select_curso", choices = c("Todos los cursos" = "TODOS"))
      return()
    }
    etiquetas <- etiquetar(cursos)
    choices <- c("Todos los cursos" = "TODOS", stats::setNames(cursos, etiquetas))
    sel <- if (!is.null(input$select_curso) && input$select_curso %in% c("TODOS", cursos)) input$select_curso else "TODOS"
    updateSelectInput(session, "select_curso", choices = choices, selected = sel)
  })
  
  datos_procesados <- reactive({
    req(input$select_curso)
    cursos <- todos_los_cursos()
    if (input$select_curso == "TODOS") {
      d <- if (length(cursos) > 0) bind_rows(cursos) else asist_vacia
      return(list(datos = d, curso = "TODOS"))
    }
    d <- if (input$select_curso %in% names(cursos)) cursos[[input$select_curso]] else asist_vacia
    list(datos = d, curso = input$select_curso)
  })
  
  alumnos_curso <- reactive({
    req(input$select_curso)
    a <- unique(datos_procesados()$datos$Nombre)
    v <- notas_data()$vinc
    if (input$select_curso != "TODOS") v <- v[v$Curso == input$select_curso, , drop = FALSE]
    n <- v$Alumno[!v$Vinculado | length(a) == 0]
    p <- character(0)
    if (pdd_cargado()) {
      pd <- pdd_data()
      if (input$select_curso != "TODOS") pd <- pd[pd$Curso_Canon == input$select_curso, , drop = FALSE]
      p <- pd$Alumno_Canon[!pd$Vinculado]
    }
    todos <- unique(c(a, n, p))
    sort(todos[es_nombre_alumno(todos)])
  })
  
  observeEvent(alumnos_curso(), {
    alumnos <- alumnos_curso()
    sel <- if (!is.null(input$select_alumno) && input$select_alumno %in% alumnos) input$select_alumno else alumnos[1]
    updateSelectInput(session, "select_alumno", choices = alumnos, selected = sel)
  })
  
  output$resumen_carga <- renderUI({
    partes <- list()
    resumen <- function(lst, nombre) {
      if (length(lst) == 0) return(NULL)
      est <- vapply(lst, function(e) e$estado, character(1))
      sprintf("%s: %d archivo(s): %d OK, %d sin datos, %d error.",
              nombre, length(lst), sum(est == "OK"), sum(est == "Sin notas aún"), sum(est == "Error"))
    }
    partes <- c(resumen(asistencia_parseada(), "Asistencia"),
                resumen(notas_parseadas(), "Notas"),
                resumen(pdd_parseada(), "PDD"))
    if (length(partes) == 0) return(NULL)
    tags$small(class = "text-muted", lapply(partes, function(x) tagList(x, tags$br())))
  })
  
  maestro <- reactive({
    a <- if (asist_cargada()) {
      asist_resumen() %>% transmute(Curso, Alumno = Nombre, Asistencia = Pct, MaxRacha)
    } else data.frame(Curso = character(), Alumno = character(), Asistencia = numeric(),
                      MaxRacha = integer(), stringsAsFactors = FALSE)
    
    n <- if (notas_cargadas() && nrow(prom_base()) > 0) {
      pg_alumno(prom_base()) %>% select(Curso, Alumno, PG, N_Rojas)
    } else data.frame(Curso = character(), Alumno = character(), PG = numeric(),
                      N_Rojas = integer(), stringsAsFactors = FALSE)
    
    p <- if (pdd_cargado()) {
      pdd_data() %>%
        group_by(Curso = Curso_Canon, Alumno = Alumno_Canon) %>%
        summarise(Logro_PDD = mean(Logro, na.rm = TRUE),
                  N_Insuf = sum(Logro < UMBRAL_LOGRO_ELEM, na.rm = TRUE), .groups = "drop")
    } else data.frame(Curso = character(), Alumno = character(), Logro_PDD = numeric(),
                      N_Insuf = integer(), stringsAsFactors = FALSE)
    
    base <- bind_rows(a[, c("Curso", "Alumno")], n[, c("Curso", "Alumno")], p[, c("Curso", "Alumno")]) %>% distinct()
    if (nrow(base) == 0) {
      return(data.frame(Curso = character(), Alumno = character(), Asistencia = numeric(),
                        MaxRacha = integer(), PG = numeric(), N_Rojas = integer(),
                        Logro_PDD = numeric(), N_Insuf = integer(), Riesgo_Asist = logical(),
                        Riesgo_Nota = logical(), Riesgo_PDD = logical(), N_Riesgos = integer(),
                        N_Fuentes = integer(), stringsAsFactors = FALSE))
    }
    
    base %>%
      left_join(a, by = c("Curso", "Alumno")) %>%
      left_join(n, by = c("Curso", "Alumno")) %>%
      left_join(p, by = c("Curso", "Alumno")) %>%
      mutate(
        Riesgo_Asist = !is.na(Asistencia) & Asistencia < UMBRAL_ASIST,
        Riesgo_Nota  = !is.na(N_Rojas) & N_Rojas > 0,
        Riesgo_PDD   = !is.na(N_Insuf) & N_Insuf > 0,
        N_Riesgos = as.integer(Riesgo_Asist) + as.integer(Riesgo_Nota) + as.integer(Riesgo_PDD),
        N_Fuentes = as.integer(!is.na(Asistencia)) + as.integer(!is.na(PG)) + as.integer(!is.na(Logro_PDD))
      )
  })
  
