  output$resumen_ejecutivo <- renderUI({
    validate(need(asist_cargada() || notas_cargadas() || pdd_cargado(),
                  "Carga archivos de asistencia, notas o PDD para ver el resumen ejecutivo."))
    b <- function(x) paste0("<b>", x, "</b>")
    tarjeta <- function(titulo, items, accent) {
      card(style = paste0("border-top: 4px solid ", accent, ";"),
           card_header(titulo),
           if (length(items) == 0) {
             tags$p(class = "text-muted", "Sin datos cargados para esta fuente.")
           } else {
             tags$ul(class = "insight-list", lapply(items, function(x) tags$li(HTML(x))))
           })
    }
    
    it_asist <- character(0)
    if (asist_cargada()) {
      d <- datos_globales()
      ar <- asist_resumen()
      pc <- d %>% group_by(Curso) %>% summarise(Pct = mean(Estado == "Asistió") * 100, .groups = "drop")
      peor <- pc[which.min(pc$Pct), ]; mejor <- pc[which.max(pc$Pct), ]
      rr <- ar[which.max(ar$MaxRacha), ]
      it_asist <- c(
        sprintf("Asistencia global: %s en %d curso(s).", b(sprintf("%.1f%%", mean(d$Estado == "Asistió") * 100)), nrow(pc)),
        sprintf("Menor asistencia: %s (%.1f%%). Mayor: %s (%.1f%%).",
                b(etiqueta_curso_segura(peor$Curso)), peor$Pct, b(etiqueta_curso_segura(mejor$Curso)), mejor$Pct),
        sprintf("%s de %d estudiantes (%.0f%%) están bajo el %d%%.",
                b(sum(ar$Pct < UMBRAL_ASIST)), nrow(ar), mean(ar$Pct < UMBRAL_ASIST) * 100, as.integer(UMBRAL_ASIST)),
        sprintf("Racha más larga de inasistencias consecutivas: %s día(s) (%s).", b(rr$MaxRacha), rr$Nombre)
      )
    }
    
    it_notas <- character(0)
    if (notas_cargadas() && nrow(prom_filtrado()) > 0) {
      p <- prom_filtrado()
      pc <- p %>% group_by(Curso) %>% summarise(M = mean(Promedio), .groups = "drop")
      pa <- p %>% group_by(Asignatura) %>% summarise(M = mean(Promedio), .groups = "drop")
      pg <- pg_alumno(p)
      cpeor <- pc[which.min(pc$M), ]; cmejor <- pc[which.max(pc$M), ]
      apeor <- pa[which.min(pa$M), ]; amejor <- pa[which.max(pa$M), ]
      it_notas <- c(
        sprintf("Promedio general del colegio: %s (aprobación %.1f%%).", b(sprintf("%.2f", mean(p$Promedio))), mean(p$Promedio >= NOTA_ROJA) * 100),
        sprintf("Curso con menor promedio: %s (%.2f). Mayor: %s (%.2f).",
                b(etiqueta_curso_segura(cpeor$Curso)), cpeor$M, b(etiqueta_curso_segura(cmejor$Curso)), cmejor$M),
        sprintf("Asignatura más baja: %s (%.2f). Más alta: %s (%.2f).", b(apeor$Asignatura), apeor$M, b(amejor$Asignatura), amejor$M),
        sprintf("%s de %d alumnos (%.0f%%) tienen al menos una asignatura bajo %.1f.",
                b(sum(pg$N_Rojas > 0)), nrow(pg), mean(pg$N_Rojas > 0) * 100, NOTA_ROJA)
      )
    }
    
    it_pdd <- character(0)
    if (pdd_cargado()) {
      d <- pdd_data()
      pc <- d %>% group_by(Curso) %>% summarise(L = mean(Logro, na.rm = TRUE), .groups = "drop")
      pa <- d %>% group_by(Asignatura) %>% summarise(L = mean(Logro, na.rm = TRUE), .groups = "drop")
      cpeor <- pc[which.min(pc$L), ]; apeor <- pa[which.min(pa$L), ]
      it_pdd <- c(
        sprintf("Logro diagnóstico del colegio: %s (%d evaluaciones).", b(sprintf("%.1f%%", mean(d$Logro, na.rm = TRUE))), nrow(d)),
        sprintf("Curso con menor logro: %s (%.1f%%).", b(etiqueta_curso_segura(cpeor$Curso)), cpeor$L),
        sprintf("Asignatura con menor logro: %s (%.1f%%).", b(apeor$Asignatura), apeor$L),
        sprintf("%s (%.0f%%) en nivel insuficiente (<%d%%).",
                b(sum(d$Logro < UMBRAL_LOGRO_ELEM, na.rm = TRUE)), mean(d$Logro < UMBRAL_LOGRO_ELEM, na.rm = TRUE) * 100, UMBRAL_LOGRO_ELEM)
      )
      dd <- d %>% filter(!is.na(Sexo))
      if (length(unique(dd$Sexo)) == 2) {
        lf <- mean(dd$Logro[dd$Sexo == "F"], na.rm = TRUE); lm_ <- mean(dd$Logro[dd$Sexo == "M"], na.rm = TRUE)
        it_pdd <- c(it_pdd, sprintf("Brecha por sexo: mujeres %.1f%% vs hombres %.1f%% (%+.1f pts).", lf, lm_, lf - lm_))
      }
    }
    
    it_int <- character(0)
    m <- maestro() %>% filter(N_Fuentes >= 2)
    if (nrow(m) > 0) {
      it_int <- c(
        sprintf("%s alumnos con datos en 2 o más fuentes.", b(nrow(m))),
        sprintf("%s con 2 o más factores de riesgo (%.0f%%).", b(sum(m$N_Riesgos >= 2)), mean(m$N_Riesgos >= 2) * 100),
        sprintf("%s con los 3 factores a la vez (asistencia, notas y PDD).", b(sum(m$N_Riesgos == 3 & m$N_Fuentes == 3)))
      )
    }
    
    tagList(
      layout_columns(col_widths = c(4, 4, 4),
                     tarjeta("📅 Asistencia", it_asist, "#2f6db5"),
                     tarjeta("📝 Notas", it_notas, "#7fb3e0"),
                     tarjeta("🎯 Diagnóstico PDD", it_pdd, "#f0a030")),
      tarjeta("🔗 Riesgo integral (cruce de fuentes)", it_int, "#d64550")
    )
  })
  
