  observeEvent(input$click_notas_rangos, {
    clk <- input$click_notas_rangos
    req(clk, notas_cargadas())
    r <- rangos_data()
    req(!is.null(r))
    
    idx_y <- round(clk$y)
    if (is.na(idx_y) || idx_y < 1 || idx_y > length(r$niveles)) return()
    curso_sel <- r$niveles[idx_y]
    curso_orig <- r$d$Curso[as.character(r$d$Etiqueta) == curso_sel][1]
    
    sub_d <- r$d %>% filter(as.character(Etiqueta) == curso_sel)
    total_n <- sum(sub_d$n)
    if (total_n == 0) return()
    cuenta <- function(rg) sum(sub_d$n[as.character(sub_d$Rango) == rg])
    lim1 <- cuenta("6.0-7.0") / total_n
    lim2 <- (cuenta("6.0-7.0") + cuenta("5.0-5.9")) / total_n
    lim3 <- (cuenta("6.0-7.0") + cuenta("5.0-5.9") + cuenta("4.0-4.9")) / total_n
    
    rango_sel <- if (clk$x <= lim1) "6.0-7.0" else if (clk$x <= lim2) "5.0-5.9" else if (clk$x <= lim3) "4.0-4.9" else "< 4.0"
    
    pg_c <- pg_alumno(r$d_prom) %>% filter(Curso == curso_orig) %>% select(Alumno, PG)
    datos_modal_rangos(
      r$d_prom %>%
        filter(Curso == curso_orig, es_nombre_alumno(Alumno)) %>%
        mutate(Rango = rangos_nota(Promedio)) %>%
        left_join(pg_c, by = "Alumno")
    )
    
    showModal(modalDialog(
      title = paste("Calificaciones en", curso_sel),
      div(class = "mb-3",
          selectInput("modal_select_rango", "Filtrar por rango:",
                      choices = c("Todos los rangos" = "TODOS", "< 4.0 (rojo)" = "< 4.0",
                                  "4.0 - 4.9" = "4.0-4.9", "5.0 - 5.9" = "5.0-5.9", "6.0 - 7.0" = "6.0-7.0"),
                      selected = rango_sel)),
      tableOutput("tabla_modal_click_rangos"),
      easyClose = TRUE, size = "l", footer = modalButton("Cerrar")
    ))
  })
  
