    if (nrow(d) == 0) return()
    cursos_pdd <- sort(unique(d$Curso))
    asigs_pdd  <- sort(unique(d$Asignatura))
    updateSelectInput(session, "pdd_filtro_curso", choices = c("Todos los cursos evaluados", cursos_pdd), selected = "Todos los cursos evaluados")
    updateSelectInput(session, "pdd_filtro_asig", choices = c("Todas", asigs_pdd), selected = "Todas")
    updateSelectInput(session, "pdd_nom_curso", choices = c("Todos los cursos", cursos_pdd), selected = "Todos los cursos")
    updateSelectInput(session, "pdd_nom_asig", choices = c("Todas las asignaturas", asigs_pdd), selected = "Todas las asignaturas")
  })
  
  observeEvent(input$btn_limpiar_pdd_nom, {
    updateSelectInput(session, "pdd_nom_curso", selected = "Todos los cursos")
    updateSelectInput(session, "pdd_nom_asig", selected = "Todas las asignaturas")
    updateSelectInput(session, "pdd_nom_nivel", selected = "Todos los niveles")
    updateSelectInput(session, "pdd_nom_genero", selected = "TODOS")
    updateTextInput(session, "pdd_nom_busqueda", value = "")
  })
  
  pdd_filtrado <- reactive({
    d <- pdd_data()
    if (nrow(d) == 0) return(d)
    if (!is.null(input$pdd_filtro_curso) && input$pdd_filtro_curso != "Todos los cursos evaluados") d <- d %>% filter(Curso == input$pdd_filtro_curso)
    if (!is.null(input$pdd_filtro_asig) && input$pdd_filtro_asig != "Todas") d <- d %>% filter(Asignatura == input$pdd_filtro_asig)
    d
  })
  
  pdd_nomina_filtrada <- reactive({
    d <- pdd_data()
    if (nrow(d) == 0) return(d)
    if (!is.null(input$pdd_nom_curso) && input$pdd_nom_curso != "Todos los cursos") d <- d %>% filter(Curso == input$pdd_nom_curso)
    if (!is.null(input$pdd_nom_asig) && input$pdd_nom_asig != "Todas las asignaturas") d <- d %>% filter(Asignatura == input$pdd_nom_asig)
    if (!is.null(input$pdd_nom_nivel) && input$pdd_nom_nivel != "Todos los niveles") d <- d %>% filter(Nivel_Logro == input$pdd_nom_nivel)
    if (!is.null(input$pdd_nom_genero) && input$pdd_nom_genero != "TODOS") d <- d %>% filter(Sexo == input$pdd_nom_genero)
    if (!is.null(input$pdd_nom_busqueda) && nzchar(trimws(input$pdd_nom_busqueda))) {
      q_norm <- norm_txt(trimws(input$pdd_nom_busqueda))
      q_digits <- gsub("[^A-Z0-9]", "", q_norm)
      match_nom <- grepl(q_norm, norm_txt(d$Alumno), fixed = TRUE)
      match_rut <- if (nzchar(q_digits)) grepl(q_digits, gsub("[^A-Z0-9]", "", d$RUT), fixed = TRUE) else FALSE
      d <- d[match_nom | match_rut, , drop = FALSE]
    }
    d
  })
  
  output$kpi_pdd_logro <- renderUI({
    d <- pdd_filtrado()
    if (nrow(d) == 0) return(kpi_val("s/d", "text-muted"))
    l <- mean(d$Logro, na.rm = TRUE)
    kpi_val(sprintf("%.1f%%", l), if (l < UMBRAL_LOGRO_ELEM) "text-danger" else if (l < UMBRAL_LOGRO_ADEC) "text-warning" else "text-success")
  })
  output$kpi_pdd_nota <- renderUI({
    d <- pdd_filtrado()
    if (nrow(d) == 0) return(kpi_val("s/d", "text-muted"))
    kpi_val(sprintf("%.2f", mean(d$Nota, na.rm = TRUE)))
  })
  output$kpi_pdd_evaluados <- renderUI({
    d <- pdd_filtrado()
    kpi_val(if (nrow(d) == 0) "0" else as.character(length(unique(d$RUT))))
  })
  output$kpi_pdd_insuficiente <- renderUI({
    d <- pdd_filtrado()
    if (nrow(d) == 0) return(kpi_val("s/d", "text-muted"))
    n <- sum(d$Logro < UMBRAL_LOGRO_ELEM, na.rm = TRUE)
    kpi_val(sprintf("%.1f%% (%d)", n / nrow(d) * 100, n), "text-danger")
  })
  
  output$plot_pdd_cursos <- renderPlot({
    validate(need(pdd_cargado(), "Sube archivos de diagnóstico PDD."))
    d <- pdd_filtrado()
    validate(need(nrow(d) > 0, "No hay datos para el filtro seleccionado."))
    res <- d %>% group_by(Curso, Asignatura) %>% summarise(Logro_Medio = mean(Logro, na.rm = TRUE), .groups = "drop")
    
    ggplot(res, aes(x = reorder(Curso, Logro_Medio), y = Logro_Medio, fill = Asignatura)) +
      geom_col(position = position_dodge(width = 0.75), width = 0.7) +
      geom_hline(yintercept = UMBRAL_LOGRO_ELEM, color = col_rojo, linetype = "dashed", linewidth = 0.9) +
      geom_hline(yintercept = UMBRAL_LOGRO_ADEC, color = col_azul, linetype = "dotted", linewidth = 0.9) +
      geom_text(aes(label = sprintf("%.1f%%", Logro_Medio)), position = position_dodge(width = 0.75),
                hjust = -0.15, fontface = "bold", size = 3.5) +
      coord_flip() +
      scale_y_continuous(limits = c(0, 105), breaks = seq(0, 100, 20), expand = expansion(mult = c(0, 0.08))) +
      scale_fill_manual(values = paleta_cat) +
      labs(title = "Porcentaje de logro diagnóstico",
           subtitle = sprintf("Roja: %d%% (elemental) | Azul: %d%% (adecuado)", UMBRAL_LOGRO_ELEM, UMBRAL_LOGRO_ADEC),
           x = NULL, y = "% de logro promedio", fill = "Asignatura") +
      tema_dash() +
      theme(axis.text.y = element_text(size = 10.5, face = "bold"))
  })
  
  semaforo_data <- reactive({
    d <- pdd_filtrado()
    if (nrow(d) == 0) return(NULL)
    cnt <- d %>%
      filter(!is.na(Nivel_Logro)) %>%
      count(Curso, Nivel_Logro) %>%
      group_by(Curso) %>%
      mutate(Pct = n / sum(n) * 100) %>%
      ungroup()
    cnt$Nivel_Logro <- factor(cnt$Nivel_Logro, levels = niveles_logro)
    niveles <- sort(unique(cnt$Curso))
    cnt$Curso <- factor(cnt$Curso, levels = niveles)
    list(cnt = cnt, niveles = niveles, d = d)
  })
  
  output$plot_pdd_semaforo <- renderPlot({
    validate(need(pdd_cargado(), "Sube archivos de diagnóstico PDD."))
    s <- semaforo_data()
    validate(need(!is.null(s), "No hay datos para el filtro seleccionado."))
    
    ggplot(s$cnt, aes(x = Curso, y = n, fill = Nivel_Logro)) +
      geom_col(position = "fill", width = 0.7) +
      geom_text(aes(label = sprintf("%d\n(%.0f%%)", n, Pct)), position = position_fill(vjust = 0.5),
                color = "white", fontface = "bold", size = 3.2) +
      coord_flip() +
      scale_y_continuous(labels = scales::percent_format()) +
      scale_fill_manual(values = colores_logro, drop = FALSE) +
      labs(title = "Semáforo de desempeño diagnóstico",
           subtitle = "Proporción de estudiantes según nivel de aprendizaje",
           x = NULL, y = "Distribución porcentual", fill = "Nivel de logro") +
      tema_dash() +
      theme(axis.text.y = element_text(size = 10.5, face = "bold"))
  })
  
  observeEvent(input$click_pdd_semaforo, {
    clk <- input$click_pdd_semaforo
    req(clk, pdd_cargado())
    s <- semaforo_data()
    req(!is.null(s))
    idx_y <- round(clk$y)
    if (is.na(idx_y) || idx_y < 1 || idx_y > length(s$niveles)) return()
    curso_sel <- s$niveles[idx_y]
    
    sub_cnt <- s$cnt %>% filter(as.character(Curso) == curso_sel)
    total_n <- sum(sub_cnt$n)
    if (total_n == 0) return()
    n_insuf <- sum(sub_cnt$n[sub_cnt$Nivel_Logro == LV_INSU])
    n_elem  <- sum(sub_cnt$n[sub_cnt$Nivel_Logro == LV_ELEM])
    lim1 <- n_insuf / total_n
    lim2 <- (n_insuf + n_elem) / total_n
    rango_sel <- if (clk$x <= lim1) LV_INSU else if (clk$x <= lim2) LV_ELEM else LV_ADEC
    
    datos_modal_pdd(s$d %>% filter(Curso == curso_sel))
    showModal(modalDialog(
      title = paste("Diagnóstico PDD —", curso_sel),
      div(class = "mb-3",
          selectInput("modal_select_pdd_nivel", "Filtrar por nivel de logro:",
                      choices = c("Todos los niveles del curso" = "TODOS", stats::setNames(niveles_logro, niveles_logro)),
                      selected = rango_sel)),
      tableOutput("tabla_modal_click_pdd"),
      easyClose = TRUE, size = "l", footer = modalButton("Cerrar")
    ))
  })
  
  output$tabla_modal_click_pdd <- renderTable({
    req(datos_modal_pdd(), input$modal_select_pdd_nivel)
    df <- datos_modal_pdd()
    if (input$modal_select_pdd_nivel != "TODOS") df <- df %>% filter(Nivel_Logro == input$modal_select_pdd_nivel)
    validate(need(nrow(df) > 0, "No hay estudiantes en este nivel de logro para este curso."))
    df %>%
      arrange(desc(Puntaje), desc(Logro)) %>%
      transmute(`Nombre Alumno` = Alumno, RUT, Sexo = ifelse(is.na(Sexo), "-", Sexo), Asignatura,
                Puntaje = as.character(Puntaje), `% Logro` = sprintf("%.0f%%", Logro),
                `Nota PDD` = sprintf("%.1f", Nota), `Nivel de Logro` = Nivel_Logro)
  }, striped = TRUE, hover = TRUE, bordered = TRUE)
  
  output$plot_pdd_genero <- renderPlot({
    validate(need(pdd_cargado(), "Sube archivos de diagnóstico PDD."))
    d <- pdd_filtrado() %>% filter(!is.na(Sexo))
    validate(need(nrow(d) > 5, "No hay suficientes datos de sexo registrados para graficar brechas."))
    res <- d %>%
      group_by(Asignatura, Sexo) %>%
      summarise(Logro_Medio = mean(Logro, na.rm = TRUE), N = n(), .groups = "drop") %>%
      mutate(Sexo_Txt = ifelse(Sexo == "F", "Mujeres (F)", "Hombres (M)"))
    
    ggplot(res, aes(x = Asignatura, y = Logro_Medio, fill = Sexo_Txt)) +
      geom_col(position = position_dodge(width = 0.75), width = 0.65) +
      geom_text(aes(label = sprintf("%.1f%%\n(n=%d)", Logro_Medio, N)),
                position = position_dodge(width = 0.75), vjust = -0.3, fontface = "bold", size = 3.6) +
      scale_y_continuous(limits = c(0, 110), breaks = seq(0, 100, 20)) +
      scale_fill_manual(values = c("Mujeres (F)" = "#8e6bbf", "Hombres (M)" = "#2f6db5")) +
      labs(title = "Brecha de rendimiento por sexo",
           subtitle = "% de logro entre alumnas y alumnos", x = NULL, y = "% de logro promedio", fill = NULL) +
      tema_dash() +
      theme(legend.position = "top")
  })
  
  output$plot_pdd_dist <- renderPlot({
    validate(need(pdd_cargado(), "Sube archivos de diagnóstico PDD."))
    d <- pdd_filtrado()
    validate(need(nrow(d) > 0, "No hay datos para graficar."))
    
    ggplot(d, aes(x = Curso, y = Nota, fill = Asignatura)) +
      geom_boxplot(alpha = 0.5, outlier.shape = NA, width = 0.6) +
      geom_jitter(width = 0.15, size = 2, alpha = 0.6, color = "#1e293b") +
      geom_hline(yintercept = 4.0, color = col_rojo, linetype = "dashed", linewidth = 0.9) +
      scale_y_continuous(limits = c(1, 7.2), breaks = 1:7) +
      scale_fill_manual(values = paleta_cat) +
      labs(title = "Dispersión de notas PDD (1.0 - 7.0)", subtitle = "Línea roja: 4.0",
           x = NULL, y = "Nota equivalente", fill = "Asignatura") +
      tema_dash() +
      theme(axis.text.x = element_text(angle = 30, hjust = 1, face = "bold"))
  })
  
  output$pdd_contador_nomina <- renderUI({
    d_total <- pdd_data()
    if (nrow(d_total) == 0) return(NULL)
    tags$div(class = "text-muted mb-2",
             sprintf("Mostrando %d de %d registros evaluados.", nrow(pdd_nomina_filtrada()), nrow(d_total)))
  })
  
  output$tabla_pdd_estudiantes <- renderTable({
    validate(need(pdd_cargado(), "Sube archivos de diagnóstico PDD."))
    d <- pdd_nomina_filtrada()
    validate(need(nrow(d) > 0, "No hay estudiantes que coincidan con los filtros aplicados."))
    d %>%
      arrange(Logro) %>%
      transmute(Curso, `Nombre Alumno` = Alumno, RUT, Sexo = ifelse(is.na(Sexo), "-", Sexo), Asignatura,
                `% Logro` = sprintf("%.0f%%", Logro), `Nota PDD` = sprintf("%.1f", Nota),
                Puntaje = as.character(Puntaje), `Nivel de Logro` = Nivel_Logro)
  }, striped = TRUE, hover = TRUE, bordered = TRUE)
  
  output$tabla_cobertura <- renderTable({
    a <- if (asist_cargada()) {
      datos_globales() %>% group_by(Curso) %>% summarise(Asistencia = n_distinct(Nombre), .groups = "drop")
    } else data.frame(Curso = character(), Asistencia = integer())
    
    nd <- notas_data()
    n <- if (nrow(nd$det) + nrow(nd$prom) > 0) {
      bind_rows(nd$det[, c("Curso", "Asignatura")], nd$prom[, c("Curso", "Asignatura")]) %>%
        distinct() %>% count(Curso, name = "Notas")
    } else data.frame(Curso = character(), Notas = integer())
    
    p <- if (pdd_cargado()) {
      pdd_data() %>% group_by(Curso = Curso_Canon) %>% summarise(PDD = n_distinct(Asignatura), .groups = "drop")
    } else data.frame(Curso = character(), PDD = integer())
    
    cursos <- unique(c(a$Curso, n$Curso, p$Curso))
    validate(need(length(cursos) > 0, "Aún no has cargado archivos."))
    
    df <- data.frame(Curso = cursos, stringsAsFactors = FALSE) %>%
      left_join(a, by = "Curso") %>% left_join(n, by = "Curso") %>% left_join(p, by = "Curso")
    for (col in c("Asistencia", "Notas", "PDD")) if (!col %in% names(df)) df[[col]] <- NA_integer_
    
    df %>%
      mutate(Etiqueta = etiquetar(Curso)) %>%
      arrange(Etiqueta) %>%
      transmute(Curso = Etiqueta,
                `Asistencia (alumnos)` = ifelse(is.na(Asistencia), "FALTA", as.character(Asistencia)),
                `Notas (asignaturas)` = ifelse(is.na(Notas), "FALTA", as.character(Notas)),
                `PDD (asignaturas)` = ifelse(is.na(PDD), "FALTA", as.character(PDD)))
  }, striped = TRUE, hover = TRUE, bordered = TRUE)
  
  output$tabla_archivos <- renderTable({
    ent <- c(unname(asistencia_parseada()), unname(notas_parseadas()), unname(pdd_parseada()))
    validate(need(length(ent) > 0, "Aún no has cargado archivos."))
    df <- bind_rows(lapply(ent, function(e) {
      data.frame(Archivo = e$nombre, Tipo = e$tipo, Curso = e$curso_txt,
                 Asignatura = e$asignatura, Semestre = e$semestre,
                 Alumnos = as.character(e$n_alumnos),
                 `Notas / Evaluados` = as.character(e$n_notas),
                 Estado = e$estado, Detalle = e$detalle,
                 check.names = FALSE, stringsAsFactors = FALSE)
    }))
    df$Alumnos[is.na(df$Alumnos)] <- "-"
    df$`Notas / Evaluados`[is.na(df$`Notas / Evaluados`)] <- "-"
    df %>% arrange(match(Estado, c("Error", "Sin notas aún", "OK")), Tipo, Curso)
  }, striped = TRUE, hover = TRUE, bordered = TRUE)
  
  output$tabla_vinculos <- renderTable({
    validate(need(nrow(notas_data()$vinc) > 0, "Sube planillas de notas para ver la vinculación."))
    v <- notas_data()$vinc
    v %>%
      mutate(Curso_Limpio = etiquetar(Curso),
             Estado = case_when(
               Vinculado ~ "Vinculado con asistencia",
               Curso_con_asistencia ~ "SIN coincidencia en asistencia",
               TRUE ~ "Curso sin planilla de asistencia")) %>%
      arrange(Vinculado, Curso_Limpio, Nombre_Notas) %>%
      select(Curso = Curso_Limpio, `Nombre en notas` = Nombre_Notas,
             `Nombre en asistencia` = Alumno, Estado) %>%
      mutate(`Nombre en asistencia` = ifelse(Estado == "Vinculado con asistencia",
                                             trimws(`Nombre en asistencia`), "-"))
  }, striped = TRUE, hover = TRUE, bordered = TRUE)
  
  output$descargar_notas <- downloadHandler(
    filename = function() paste0("notas_consolidadas_", Sys.Date(), ".csv"),
    content = function(file) {
      out <- notas_data()$det
      if (nrow(out) > 0) {
        out <- out %>%
          mutate(Curso = etiquetar(Curso)) %>%
          select(Curso, Asignatura, Alumno, Semestre, Evaluacion, Etiqueta, Nota) %>%
          arrange(Curso, Asignatura, Alumno, Semestre, Evaluacion)
      }
      escribir_csv_excel(out, file)
    }
  )
  
  output$descargar_pdd <- downloadHandler(
    filename = function() paste0("nomina_pdd_filtrada_", Sys.Date(), ".csv"),
    content = function(file) {
      d <- pdd_nomina_filtrada()
      if (nrow(d) > 0) d <- d %>% select(Curso, Alumno, RUT, Sexo, Asignatura, Logro, Nota, Puntaje, Nivel_Logro, Archivo)
      escribir_csv_excel(d, file)
    }
  )
  
  output$descargar_riesgo <- downloadHandler(
    filename = function() paste0("riesgo_integral_", Sys.Date(), ".csv"),
    content = function(file) {
      m <- maestro()
      if (nrow(m) > 0) {
        m <- m %>%
          rowwise() %>%
          mutate(Factores = texto_factores(Riesgo_Asist, Riesgo_Nota, Riesgo_PDD)) %>%
          ungroup() %>%
          transmute(Curso = etiquetar(Curso), Alumno,
                    Asistencia_pct = round(Asistencia, 1), Racha_max_faltas = MaxRacha,
                    Promedio_notas = PG, Asignaturas_en_rojo = N_Rojas,
                    Logro_PDD_pct = round(Logro_PDD, 1), PDD_insuficientes = N_Insuf,
                    Factores_riesgo = N_Riesgos, Detalle_factores = Factores) %>%
          arrange(desc(Factores_riesgo), Curso, Alumno)
      }
      escribir_csv_excel(m, file)
    }
  )
}

